(async function(){
'use strict';
const $=id=>document.getElementById(id),esc=s=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={audits:[],importRecord:null,verification:null,implementation:[],staging:[],defects:[],rcGates:[]};
const sorted=a=>(a||[]).slice().sort((x,y)=>Date.parse(y?.at||y?.payload?.approvedAt||y?.payload?.testedAt||y?.payload?.recordedAt||0)-Date.parse(x?.at||x?.payload?.approvedAt||x?.payload?.testedAt||x?.payload?.recordedAt||0));
const rowsByType=t=>state.audits.filter(x=>x?.type===t).map(x=>x.payload||x).filter(Boolean);const latest=rows=>JK_PHASE49.latest(rows);const hashFile=async f=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',await f.arrayBuffer()))].map(x=>x.toString(16).padStart(2,'0')).join('');
function badgeClass(v){return ['PASS','PLAN_APPROVED','GUARDRAIL_PASS','STAGING_PASS','IMPLEMENTATION_EVIDENCE_RECORDED','ROLLBACK_REHEARSAL_PASS','RC_APPROVED','CLOSED','REVERIFY_PASS'].includes(v)?'PASS':['FAIL','STAGING_FAIL','IMPLEMENTATION_EVIDENCE_REJECTED','RC_BLOCKED','OPEN','TRIAGED','REVERIFY_REQUIRED'].includes(v)?'FAIL':'NOT_RUN'}
function render(){const v=state.verification||{status:'NOT_IMPORTED'},coverage=JK_PHASE49.implementationCoverage(v,state.implementation),s=latest(state.staging)||{status:'NOT_RUN'},g=latest(state.rcGates)||{status:'NOT_RECORDED'};for(const [id,val] of [['phase49InputBadge',v.status],['phase49PlanBadge',v.plan?.status||'NOT_VERIFIED'],['phase49GuardrailBadge',v.guardrail?.status||'NOT_VERIFIED'],['phase49Phase48StagingBadge',v.phase48Staging?.status||'NOT_VERIFIED'],['phase49ImplBadge',coverage.complete?'COMPLETE':state.implementation.length?'INCOMPLETE':'NOT_RECORDED'],['phase49CandidateStagingBadge',s.status],['phase49RollbackBadge',s.rollbackRehearsal?.status||'NOT_RUN'],['phase49RcBadge',g.status]])if($(id)){$(id).textContent=val;$(id).className=`status ${badgeClass(val==='COMPLETE'?'PASS':val)}`};if($('phase49SourceSha'))$('phase49SourceSha').textContent=v.bundleSha256||'-';if($('phase49RequestId')){$('phase49RequestId').innerHTML='<option value="">Select authorized request</option>'+(v.requestIds||[]).map(id=>`<option value="${esc(id)}">${esc(id)}</option>`).join('')};if($('phase49ImplementationList'))$('phase49ImplementationList').innerHTML=(v.requestIds||[]).map(id=>{const rec=state.implementation.find(x=>x.requestId===id&&x.accepted);return `<div class="decisionRow"><div><strong>${esc(id)}</strong><div class="note">${rec?esc(rec.builtArtifactRef):'implementation evidence required'}</div></div><span class="status ${badgeClass(rec?.status||'NOT_RECORDED')}">${esc(rec?.status||'NOT_RECORDED')}</span></div>`}).join('')||'<div class="note">No verified Phase 48 requests.</div>';if($('phase49DefectList'))$('phase49DefectList').innerHTML=state.defects.slice(0,8).map(d=>`<div class="decisionRow"><div><strong>${esc(d.defectId)} · ${esc(d.severity)}</strong><div class="note">${esc(d.summary)}</div></div><span class="status ${badgeClass(d.status)}">${esc(d.status)}</span></div>`).join('')||'<div class="note">No Phase 49 defects recorded.</div>';if($('phase49Export'))$('phase49Export').disabled=!state.importRecord}
async function load(){state.audits=sorted(await JK_STORAGE.listApprovalAudit());state.importRecord=rowsByType('phase49_phase48_audit_import_saved')[0]||null;state.verification=state.importRecord?.verification||null;state.implementation=rowsByType('phase49_implementation_evidence_saved');state.staging=rowsByType('phase49_candidate_staging_saved');state.defects=rowsByType('phase49_defect_saved');state.rcGates=rowsByType('phase49_rc_gate_saved');render()}
async function verifyBundle(){const file=$('phase49BundleFile').files?.[0];if(!file){$('phase49ImportMessage').textContent='Select a Phase 48 audit JSON.';return}try{const bundle=JSON.parse(await file.text()),sha=await hashFile(file),verification=JK_PHASE49.verifyPhase48AuditBundle(bundle,{computedSha256:sha,expectedSha256:$('phase49ExpectedSha').value}),record={format:'JK_ENG_PHASE49_PHASE48_AUDIT_IMPORT',version:'49.0',importId:verification.verificationId,phase48Bundle:bundle,phase48BundleMeta:{name:file.name,size:file.size,lastModified:file.lastModified,sha256:sha,expectedSha256:JK_PHASE49.normalizeHash($('phase49ExpectedSha').value)||null},verification,importedAt:new Date().toISOString()};await JK_STORAGE.appendApprovalAudit({type:'phase49_phase48_audit_import_saved',entityId:record.importId,payload:record});$('phase49ImportMessage').textContent=verification.status==='PASS'?'Phase 48 plan, guardrail, and actual staging verified. Implementation evidence is still required.':'Verification failed: '+verification.errors.join(', ');await load()}catch(e){$('phase49ImportMessage').textContent='Import failed: '+(e.message||e)}}
async function saveImplementation(){let sha=$('phase49ImplArtifactSha').value;const f=$('phase49ImplArtifactFile').files?.[0];if(f)sha=await hashFile(f);const rec=JK_PHASE49.recordImplementationEvidence({requestId:$('phase49RequestId').value,implementedBy:$('phase49ImplementedBy').value,evidence:$('phase49ImplEvidence').value,builtArtifactRef:$('phase49ImplArtifactRef').value||f?.name,builtArtifactSha256:sha},state.verification||{});if(!rec.accepted){$('phase49ImplMessage').textContent='Rejected: '+rec.errors.join(', ');return}await JK_STORAGE.appendApprovalAudit({type:'phase49_implementation_evidence_saved',entityId:rec.evidenceId,payload:rec});$('phase49ImplMessage').textContent='Implementation evidence recorded. No automatic application occurred.';await load()}
async function saveStaging(){const ids=['AUTH','DAILY_LOOP','MULTI_DEVICE_RESUME','OFFLINE_RECOVERY','ADMIN_RECOVERY','ASSET_INTEGRITY','ROLLBACK_READINESS'],cases=ids.map(id=>({id,status:$(`phase49Stage${id}Status`).value,evidence:$(`phase49Stage${id}Evidence`).value}));let csha=$('phase49CandidateSha').value,msha=$('phase49ManifestSha').value;const cf=$('phase49CandidateFile').files?.[0],mf=$('phase49ManifestFile').files?.[0];if(cf)csha=await hashFile(cf);let manifestFormat='';let manifestVersion=$('phase49ManifestVersion').value;if(mf){msha=await hashFile(mf);try{const mj=JSON.parse(await mf.text());manifestFormat=String(mj.format||'');manifestVersion=String(mj.version||manifestVersion);$('phase49ManifestVersion').value=manifestVersion}catch(_){manifestFormat='INVALID_JSON'}}const rec=JK_PHASE49.createCandidateStaging({actualStagingContext:$('phase49StagingActual').checked,stagingUrl:$('phase49StagingUrl').value,operator:$('phase49StagingOperator').value,candidateArtifactSha256:csha,assetManifestFormat:manifestFormat,assetManifestVersion:manifestVersion,assetManifestSha256:msha,cases,rollbackRehearsal:{actualRehearsal:$('phase49RollbackActual').checked,target:$('phase49RollbackTarget').value,result:$('phase49RollbackResult').value,operator:$('phase49RollbackOperator').value,evidence:$('phase49RollbackEvidence').value,restoreCandidateEvidence:$('phase49RollbackRestoreEvidence').value}},state.verification||{},state.implementation);await JK_STORAGE.appendApprovalAudit({type:'phase49_candidate_staging_saved',entityId:rec.runId,payload:rec});$('phase49StagingMessage').textContent=`${rec.status}${rec.errors.length?': '+rec.errors.join(', '):''}. Production deployment remains separate.`;await load()}
async function saveDefect(){const rec=JK_PHASE49.recordDefect({defectId:$('phase49DefectId').value,severity:$('phase49DefectSeverity').value,status:$('phase49DefectStatus').value,summary:$('phase49DefectSummary').value,evidence:$('phase49DefectEvidence').value});if(!rec.accepted){$('phase49DefectMessage').textContent='Rejected: '+rec.errors.join(', ');return}await JK_STORAGE.appendApprovalAudit({type:'phase49_defect_saved',entityId:rec.defectId,payload:rec});$('phase49DefectMessage').textContent='Defect state recorded.';await load()}
async function saveRcGate(){const preservations={processScoringPreserved:$('phase49PreserveProcess').checked,textbookReturnLoopPreserved:$('phase49PreserveTextbook').checked,evidenceMarkingPreserved:$('phase49PreserveEvidence').checked,originalRetryPreserved:$('phase49PreserveRetry').checked,nonAnxietyPacingPreserved:$('phase49PreservePacing').checked,dailyStructurePreserved:$('phase49PreserveDaily').checked},impacts={numericCountdownVisible:$('phase49ImpactCountdown').checked,bypassProcessScoring:$('phase49ImpactProcessBypass').checked,bypassTextbookReturn:$('phase49ImpactTextbookBypass').checked,dailyTimingMutation:$('phase49ImpactDailyTiming').checked,bypassEvidenceMarking:false,bypassOriginalRetry:false,automaticImplementation:false,automaticDeployment:false,automaticRollback:false,automaticPersonalizationThresholdChange:false,automaticContentApply:false};const rec=JK_PHASE49.createRCGate({operator:$('phase49RcOperator').value,evidence:$('phase49RcEvidence').value,confirmationPhrase:$('phase49RcConfirm').value,preservations,impacts,guardrailRegression:$('phase49GuardrailRegression').checked,contentApprovalMismatch:$('phase49ContentMismatch').checked,learningLoopInvariantRegression:$('phase49LoopRegression').checked,dailyStructureRegression:$('phase49DailyRegression').checked,assetIdentityFailure:$('phase49AssetIdentityFailure').checked},state.verification||{},state.implementation,latest(state.staging)||{},state.defects);await JK_STORAGE.appendApprovalAudit({type:'phase49_rc_gate_saved',entityId:rec.gateId,payload:rec});$('phase49RcMessage').textContent=`${rec.status}${rec.errors.length?': '+rec.errors.join(', '):''}. External v1.0.4 release remains NOT_RUN.`;await load()}
function downloadJson(payload,name){const b=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportAudit(){downloadJson(JK_PHASE49.buildPhase49AuditBundle({phase48BundleMeta:state.importRecord?.phase48BundleMeta||null,phase48AuditVerification:state.verification,implementationEvidence:state.implementation,candidateStagingRuns:state.staging,defects:state.defects,rcGates:state.rcGates}),`JK_ENG_Phase49_v104_Implementation_Staging_RC_${new Date().toISOString().slice(0,10)}.json`)}
await JK_AUTH.requireRole('admin');await JK_STORAGE.init();$('phase49VerifyBundle').onclick=verifyBundle;$('phase49ImplSave').onclick=saveImplementation;$('phase49StagingSave').onclick=saveStaging;$('phase49DefectSave').onclick=saveDefect;$('phase49RcSave').onclick=saveRcGate;$('phase49Export').onclick=exportAudit;await load();
})().catch(e=>{console.error(e);const el=document.getElementById('phase49ImportMessage');if(el)el.textContent=String(e.message||e)});
